create extension if not exists pgcrypto;
create type source as enum ('manual','ai_text','image','integration','seed');
create type workout_type as enum ('gym','walk','swim','run','cycle','yoga','sports','other');
create type attachment_type as enum ('meal_photo','zepp_screenshot','progress_photo','other');
create table food_logs (id uuid primary key default gen_random_uuid(), user_id uuid not null, meal_type text, total_calories numeric, total_protein numeric, total_carbs numeric, total_fat numeric, total_fiber numeric, notes text, source source not null default 'manual', created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz);
create table food_items (id uuid primary key default gen_random_uuid(), food_log_id uuid not null references food_logs(id), food_name text not null, quantity numeric, unit text, calories numeric, protein numeric, carbs numeric, fat numeric, fiber numeric, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz);
create table workout_sessions (id uuid primary key default gen_random_uuid(), user_id uuid not null, workout_type workout_type not null, start_time timestamptz, end_time timestamptz, duration_minutes integer, calories_burned integer, source source not null default 'manual', notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz);
create table strength_exercises (id uuid primary key default gen_random_uuid(), workout_session_id uuid not null references workout_sessions(id), exercise_name text not null, muscle_group text, equipment text, order_index integer not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz);
create table strength_sets (id uuid primary key default gen_random_uuid(), strength_exercise_id uuid not null references strength_exercises(id), set_number integer not null, reps integer, weight numeric, rir integer, rpe numeric, completed boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz);
create table cardio_sessions (id uuid primary key default gen_random_uuid(), workout_session_id uuid not null references workout_sessions(id), activity text not null, distance numeric, steps integer, pace text, average_hr integer, max_hr integer, elevation numeric, laps integer, pool_length numeric, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz);
create table sleep_logs (id uuid primary key default gen_random_uuid(), user_id uuid not null, bedtime timestamptz not null, wake_time timestamptz not null, duration integer not null, quality integer, source source not null default 'manual', created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz);
create table weight_logs (id uuid primary key default gen_random_uuid(), user_id uuid not null, weight numeric not null, body_fat numeric, muscle_mass numeric, visceral_fat numeric, source source not null default 'manual', created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz);
create table attachments (id uuid primary key default gen_random_uuid(), user_id uuid not null, attachment_type attachment_type not null, storage_path text not null, linked_table text, linked_record_id uuid, uploaded_at timestamptz not null default now(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz);
create index food_logs_user_idx on food_logs(user_id); create index workout_sessions_user_idx on workout_sessions(user_id); create index sleep_logs_user_idx on sleep_logs(user_id); create index weight_logs_user_idx on weight_logs(user_id); create index attachments_user_idx on attachments(user_id);
insert into storage.buckets (id, name, public) values ('mealfix-attachments','mealfix-attachments',false) on conflict (id) do nothing;
